from scipy.optimize import least_squares
def fit(f,p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: f(p)-sigma, p0, max_nfev=5000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return best, np.mean((best.fun)**2)/np.var(sigma)
